package com.dormrepair.v2.catalog;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import com.dormrepair.v2.platform.migration.V2DatabaseTarget;
/** Explicit synthetic dataset; no user credentials, no destructive operations. */
public final class DemoInitializer {
 private final JdbcTemplate jdbc;private int created,retained;
 private DemoInitializer(DataSource ds){jdbc=new JdbcTemplate(ds);}
 public static Map<String,Integer> initialize(DataSource ds){return run(ds,false);}
 static Map<String,Integer> initializeForTest(DataSource ds){return run(ds,true);}
 private static Map<String,Integer> run(DataSource ds,boolean test){return new TransactionTemplate(new DataSourceTransactionManager(ds)).execute(status->{var tool=new DemoInitializer(ds);tool.jdbc.execute((org.springframework.jdbc.core.ConnectionCallback<Void>)c->{V2DatabaseTarget.verify(c);if(test)V2DatabaseTarget.requireTestReset(c);else if(!c.getCatalog().equals("dorm_repair_v2_dev"))throw new IllegalStateException("Demo requires v2_dev");return null;});if(tool.jdbc.queryForObject("select count(*) from v2_business_history.flyway_schema_history where version='6' and success",Integer.class)!=1)throw new IllegalStateException("V6 required");tool.jdbc.queryForObject("select guard_key from public.system_guard where guard_key='rbac-admin' for update",String.class);tool.jdbc.queryForObject("select guard_key from public.system_guard where guard_key='foundation-catalog' for update",String.class);tool.seed();return Map.of("created",tool.created,"retained",tool.retained);});}
 long ensure(String table,LinkedHashMap<String,Object> values,String...keys){String predicate=String.join(" and ",Arrays.stream(keys).map(k->k+"=?").toList());Object[] args=Arrays.stream(keys).map(values::get).toArray();var found=jdbc.queryForList("select * from public."+table+" where "+predicate,args);if(!found.isEmpty()){var existing=found.getFirst();for(String key:values.keySet()){if(key.equals("name")||key.equals("enabled")||key.equals("sort_order")||key.equals("estimated_minutes")||key.equals("status")||key.startsWith("qr_"))continue;if(!Objects.equals(String.valueOf(existing.get(key)),String.valueOf(values.get(key))))throw new IllegalStateException("Synthetic relationship conflict in "+table);}retained++;return ((Number)existing.get("id")).longValue();}String columns=String.join(",",values.keySet());long id=jdbc.queryForObject("insert into public."+table+"("+columns+") values ("+String.join(",",Collections.nCopies(values.size(),"?"))+") returning id",Long.class,values.values().toArray());created++;return id;}
 static LinkedHashMap<String,Object> v(Object...args){var map=new LinkedHashMap<String,Object>();for(int i=0;i<args.length;i+=2)map.put((String)args[i],args[i+1]);return map;}
 void seed(){var buildings=new ArrayList<Long>();var floors=new ArrayList<Long>();var rooms=new ArrayList<Long>();for(int c=1;c<=2;c++){long campus=ensure("campus",v("code","SYNTHETIC_CAMPUS_"+c,"name","虚构校区"+c),"code");for(int b=1;b<=2;b++){String bc="SYNTHETIC_BUILDING_"+c+"_"+b;long building=ensure("building",v("code",bc,"name","虚构楼栋"+c+"_"+b,"campus_id",campus),"code");buildings.add(building);for(int f=1;f<=3;f++){long floor=ensure("building_floor",v("building_id",building,"floor_no",f,"name","虚构楼层"+f),"building_id","floor_no");floors.add(floor);for(int room=1;room<=4;room++)rooms.add(ensure("room",v("floor_id",floor,"room_no","SYNTHETIC_"+room,"name","虚构房间"+room,"kind",room==4?"PUBLIC":"PRIVATE"),"floor_id","room_no"));}}}
 var items=new ArrayList<Long>();var roots=jdbc.queryForList("select id from public.repair_category where parent_id is null order by sort_order,id",Long.class);for(int root=0;root<roots.size();root++){long category=ensure("repair_category",v("code","SYNTHETIC_CATEGORY_"+root,"name","虚构故障分类"+root,"parent_id",roots.get(root)),"code");for(int n=0;n<4;n++)items.add(ensure("repair_item",v("code","SYNTHETIC_ITEM_"+root+"_"+n,"name","虚构故障项目"+root+"_"+n,"category_id",category,"estimated_minutes",30,"is_quick",n==0),"code"));}
 var types=new ArrayList<Long>();for(int n=0;n<12;n++){boolean newType=jdbc.queryForObject("select count(*)=0 from public.facility_type where code=?",Boolean.class,"SYNTHETIC_TYPE_"+n);long type=ensure("facility_type",v("code","SYNTHETIC_TYPE_"+n,"name","虚构设施类型"+n),"code");types.add(type);long item=items.get(n%items.size());if(newType)jdbc.update("insert into public.facility_type_repair_item values (?,?) on conflict do nothing",type,item);}
 for(int n=0;n<60;n++){long building=buildings.get(n%4);var values=v("asset_no","SYNTHETIC_ASSET_"+n,"name","虚构设施"+n,"facility_type_id",types.get(n%12),"building_id",building,"status","ACTIVE");if(n%3==0){long floor=floors.get((n%4)*3);long room=rooms.get((n%4)*12);values.put("floor_id",floor);values.put("room_id",room);}else values.put("public_zone","SYNTHETIC_虚构公共区域");String token=UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");values.put("qr_token",token);values.put("qr_token_hash",CatalogService.hash(token));ensure("facility",values,"asset_no");}
 jdbc.update("insert into public.audit_event(action,target_type,request_id,details) values ('SYNTHETIC_DEMO_INITIALIZED','CATALOG',?,jsonb_build_object('created',?,'retained',?))",UUID.randomUUID().toString(),created,retained);
 }
}
